def skill(state, t, dt):
    d = state["dist_to_hurdle"] - state["hurdle_x"] + state["x"]
    vx_target = min(1.0, max(0.5, 0.6 + 0.4 * ((d < 0.8) and (d > 0.2))))
    stride_target = 0.5 if d > 0.5 else (0.3 if abs(d) < 0.1 else 0.4)
    lift_target = 0.35 + 0.6 * max(0, -d / 0.1)
    torso_pitch = min(0.25, max(-0.15, lift_target - 0.3))
    phase_bias = -2.0 if abs(d) < 0.3 else (1.0 if d > 0 else 0.0)
    return {"vx": vx_target, "stride": stride_target, "lift": lift_target,
            "phase_bias": phase_bias, "torso_pitch": torso_pitch}
